class SegmentTree {
public:
    explicit SegmentTree(const std::vector<int>& xs)
        : xs(xs), n(xs.size() - 1), coveredCount(4 * n, 0), coveredWidth(4 * n, 0) {}

    void add(int i, int j, int val) {
        add(0, 0, n - 1, i, j, val);
    }

    int getCoveredWidth() const {
        return coveredWidth[0];
    }

private:
    const int n;
    std::vector<int> xs;
    std::vector<int> coveredCount;
    std::vector<int> coveredWidth;

    void add(int treeIndex, int lo, int hi, int i, int j, int val) {
        if (j <= xs[lo] || xs[hi + 1] <= i) return;
        if (i <= xs[lo] && xs[hi + 1] <= j) {
            coveredCount[treeIndex] += val;
        } else {
            int mid = (lo + hi) / 2;
            add(2 * treeIndex + 1, lo, mid, i, j, val);
            add(2 * treeIndex + 2, mid + 1, hi, i, j, val);
        }

        if (coveredCount[treeIndex] > 0) {
            coveredWidth[treeIndex] = xs[hi + 1] - xs[lo];
        } else if (lo == hi) {
            coveredWidth[treeIndex] = 0;
        } else {
            coveredWidth[treeIndex] = coveredWidth[2 * treeIndex + 1] + coveredWidth[2 * treeIndex + 2];
        }
    }
};

class Solution {
public:
    double separateSquares(std::vector<std::vector<int>>& squares) {
        std::vector<std::tuple<int, int, int, int>> events;
        std::set<int> xs_set;

        for (const auto& sq : squares) {
            int x = sq[0], y = sq[1], l = sq[2];
            events.emplace_back(y, 1, x, x + l);
            events.emplace_back(y + l, -1, x, x + l);
            xs_set.insert(x);
            xs_set.insert(x + l);
        }

        std::sort(events.begin(), events.end());
        std::vector<int> xs(xs_set.begin(), xs_set.end());

        SegmentTree tree1(xs);
        long long total_area = 0;
        int prev_y = std::get<0>(events[0]);
        for (const auto& [y, delta, xl, xr] : events) {
            total_area += 1LL * tree1.getCoveredWidth() * (y - prev_y);
            tree1.add(xl, xr, delta);
            prev_y = y;
        }

        double half_area = total_area / 2.0;
        SegmentTree tree2(xs);
        double area = 0;
        prev_y = std::get<0>(events[0]);
        for (const auto& [y, delta, xl, xr] : events) {
            int w = tree2.getCoveredWidth();
            double gain = 1.0 * w * (y - prev_y);
            if (area + gain >= half_area) {
                return prev_y + (half_area - area) / w;
            }
            area += gain;
            tree2.add(xl, xr, delta);
            prev_y = y;
        }
        return 0.0;
    }
};

import java.util.*;

class SegmentTree {
    private int n;
    private int[] xs;
    private int[] count;
    private int[] width;

    public SegmentTree(int[] xs) {
        this.xs = xs;
        this.n = xs.length - 1;
        this.count = new int[4 * n];
        this.width = new int[4 * n];
    }

    public void add(int i, int j, int val) {
        add(0, 0, n - 1, i, j, val);
    }

    private void add(int idx, int lo, int hi, int i, int j, int val) {
        if (j <= xs[lo] || xs[hi + 1] <= i) return;
        if (i <= xs[lo] && xs[hi + 1] <= j) {
            count[idx] += val;
        } else {
            int mid = (lo + hi) / 2;
            add(2 * idx + 1, lo, mid, i, j, val);
            add(2 * idx + 2, mid + 1, hi, i, j, val);
        }
        if (count[idx] > 0) {
            width[idx] = xs[hi + 1] - xs[lo];
        } else if (lo == hi) {
            width[idx] = 0;
        } else {
            width[idx] = width[2 * idx + 1] + width[2 * idx + 2];
        }
    }

    public int getWidth() {
        return width[0];
    }
}

class Solution {
    public double separateSquares(int[][] squares) {
        List<int[]> events = new ArrayList<>();
        TreeSet<Integer> xsSet = new TreeSet<>();
        for (int[] sq : squares) {
            int x = sq[0], y = sq[1], l = sq[2];
            events.add(new int[]{y, 1, x, x + l});
            events.add(new int[]{y + l, -1, x, x + l});
            xsSet.add(x);
            xsSet.add(x + l);
        }
        events.sort(Comparator.comparingInt(a -> a[0]));
        int[] xs = new int[xsSet.size()];
        int idx = 0;
        for (int x : xsSet) xs[idx++] = x;

        SegmentTree tree1 = new SegmentTree(xs);
        long totalArea = 0;
        int prevY = events.get(0)[0];
        for (int[] ev : events) {
            totalArea += (long)tree1.getWidth() * (ev[0] - prevY);
            tree1.add(ev[2], ev[3], ev[1]);
            prevY = ev[0];
        }

        double halfArea = totalArea / 2.0;
        SegmentTree tree2 = new SegmentTree(xs);
        double area = 0;
        prevY = events.get(0)[0];
        for (int[] ev : events) {
            int w = tree2.getWidth();
            double gain = (double)w * (ev[0] - prevY);
            if (area + gain >= halfArea) {
                return prevY + (halfArea - area) / w;
            }
            area += gain;
            tree2.add(ev[2], ev[3], ev[1]);
            prevY = ev[0];
        }
        return 0.0;
    }
}

